function group(p){const c=b[p],stack=[p],seen=new Set([p]),lib=new Set();while(stack.length){const q=stack.pop();for(const n of h.neighbors(q)){if(b[n]===".")lib.add(n);else if(b[n]===c&&!seen.has(n)){seen.add(n);stack.push(n);}}}return {stones:[...seen],lib:[...lib]};}
for(let ri=0;ri<log.responses.length;ri++){for(let k=0;k<2;k++){const m=moves[mi++];if(m.point!=="pass"){if(b[m.point]!==".")throw Error("occupied");b[m.point]=m.color;let removed=[];for(const n of h.neighbors(m.point)){if(b[n]!=="."&&b[n]!==m.color){const g=group(n);if(!g.lib.length){for(const q of g.stones)b[q]=".";removed.push(...g.stones);}}}if(!group(m.point).lib.length)throw Error("suicide");caps[m.color]+=removed.length;if(removed.length)events.push({move:mi,color:m.color,point:m.point,captured:removed.sort()});if(history.length>=1&&JSON.stringify(b)===history[history.length-1])throw Error("ko");}history.push(JSON.stringify(b));}
