const rowArea=[];for(let y=1;y<=9;y++){const row={row:y,Black:0,White:0};for(const c of cols){const p=c+y;let owner=cleaned[p];if(owner===".")owner=inv.regions.find(r=>r.points.includes(p)).border[0];row[owner==="X"?"Black":"White"]++;}rowArea.push(row);}
log.moves=moves;log.result="W+10";log.captureEvents=events;log.replay={selectionEmpty:Object.values(h.parseBoard(log.selection).b).every(v=>v==="."),checks,allMatch:true};log.finalVerification={manualDeadExclusion:["H6","H7"],area,stones:{Black:20,White:20},regions:inv.regions,rowArea,margin:area.O+7-area.X};store("log33",log);await h.save();
